import numpy as np
import pandas as pd

from .backtest import origins

LEVELS = np.array([0.05, 0.1, 0.25, 0.5, 0.75, 0.9, 0.95])

# %% ../nbs/07_Probabilistic/01_Probabilistic_Forecasting.ipynb #c8394f53
def pinball(y, q, level: float) -> float:
    "Mean pinball (quantile) loss of quantile forecasts `q` at `level`."
    d = np.asarray(y) - np.asarray(q)
    return float(np.mean(np.maximum(level * d, (level - 1) * d)))


def crps(y, Q, levels=LEVELS) -> float:
    "CRPS approximated by twice the mean pinball loss over the quantile `levels` (columns of `Q`)."
    return float(2 * np.mean([pinball(y, Q[:, i], l) for i, l in enumerate(levels)]))


def coverage(y, lo, hi) -> float:
    "Share of outcomes inside [lo, hi]."
    y = np.asarray(y)
    return float(np.mean((y >= lo) & (y <= hi)))


def quantile_backtest(y: pd.Series, forecaster, exclude: pd.Series | None = None, levels=LEVELS) -> pd.DataFrame:
    "Backtest a forecaster returning a (horizon, len(levels)) array; one row per scored hour, quantiles as columns."
    rows = []
    for w, o in enumerate(origins(y.index)):
        Q = np.sort(np.asarray(forecaster(y.iloc[:o], 24), dtype=float), axis=1)  # sorting removes quantile crossing
        actual = y.iloc[o:o + 24]
        df = pd.DataFrame(Q, columns=[f"q{l:g}" for l in levels], index=actual.index)
        df.insert(0, "y", actual.to_numpy())
        df.insert(0, "window", w)
        rows.append(df)
    out = pd.concat(rows)
    if exclude is not None:
        out = out[~exclude.reindex(out.index).to_numpy()]
    return out


def summarise(qb: pd.DataFrame, levels=LEVELS) -> dict:
    "CRPS, median MAE, and coverage and width of the 80% and 90% intervals."
    Q = qb[[f"q{l:g}" for l in levels]].to_numpy()
    return {"crps": crps(qb.y, Q, levels), "median MAE": float(np.mean(np.abs(qb.y - qb["q0.5"]))),
            "cover 90%": coverage(qb.y, qb["q0.05"], qb["q0.95"]), "width 90%": float(np.mean(qb["q0.95"] - qb["q0.05"])),
            "cover 80%": coverage(qb.y, qb["q0.1"], qb["q0.9"]), "width 80%": float(np.mean(qb["q0.9"] - qb["q0.1"]))}
